-- ---------- Verificación ----------
SELECT 'continente' AS tabla, COUNT(*) AS filas FROM dbo.continente          UNION ALL
SELECT 'pais',                COUNT(*)          FROM dbo.pais                UNION ALL
SELECT 'empresa',             COUNT(*)          FROM dbo.empresa             UNION ALL
SELECT 'modelo',              COUNT(*)          FROM dbo.modelo              UNION ALL
SELECT 'modelo_combustible',  COUNT(*)          FROM dbo.modelo_combustible  UNION ALL
SELECT 'modelo_opcion_motor', COUNT(*)          FROM dbo.modelo_opcion_motor;
-- Esperado: 3, 9, 31, 1218, 1267, 1311

-- Ejemplo: datos del Volkswagen Touareg SIN usar JOIN (con subconsultas)
SELECT modelo_id, nombre_modelo, motor_config, hp_min, hp_max, precio_min_usd, precio_max_usd
FROM dbo.modelo
WHERE nombre_modelo = N'Touareg';

SELECT combustible
FROM dbo.modelo_combustible
WHERE modelo_id = (SELECT modelo_id FROM dbo.modelo WHERE nombre_modelo = N'Touareg');

SELECT valor, unidad
FROM dbo.modelo_opcion_motor
WHERE modelo_id = (SELECT modelo_id FROM dbo.modelo WHERE nombre_modelo = N'Touareg');

SELECT nombre AS empresa, pais
FROM dbo.empresa
WHERE empresa_id = (SELECT empresa_id FROM dbo.modelo WHERE nombre_modelo = N'Touareg');

-- Ejemplo de consulta: precio promedio por país, autos con más de 500 hp (con subconsulta, sin JOIN)
-- SQL Server no permite una subconsulta directamente en GROUP BY, así que primero
-- se resuelve el país en una subconsulta dentro del FROM, y se agrupa por esa columna.
SELECT pais, COUNT(*) AS modelos, AVG(precio_min_usd) AS precio_promedio
FROM (
    SELECT
        precio_min_usd,
        (SELECT pais FROM dbo.empresa WHERE empresa_id = modelo.empresa_id) AS pais
    FROM dbo.modelo
    WHERE hp_min > 500
) AS t
GROUP BY pais
ORDER BY precio_promedio DESC;
GO
